drills.solution:
first = {}
with open("samples/demo.log", encoding="utf-8") as f:
    for line in f:
        parts = line.strip().split(" ")
        if len(parts) < 4 or not parts[0].startswith("20"):
            continue
        if parts[2] not in ("ERROR", "FATAL"):
            continue
        svc = parts[3].rstrip(":")
        if svc not in first:
            first[svc] = parts[1]
for svc, t in sorted(first.items(), key=lambda kv: kv[1]):
    print(t, svc)
